namespace AstroPlanner.Data.Catalog;

/// <summary>
/// Schema of <c>catalogs.sqlite</c>, the read-only catalog database generated by
/// <c>tools/AstroPlanner.DataBuilder</c> (writer) and read by <see cref="SqliteCatalogRepository"/>.
/// Bump <see cref="Version"/> on any incompatible change.
/// </summary>
public static class CatalogSchema
{
    /// <summary>Stored in <c>meta.schema_version</c>.</summary>
    public const int Version = 2;

    /// <summary>File name inside <c>data/build</c> and of the embedded resource.</summary>
    public const string FileName = "catalogs.sqlite";

    public const string CreateTables = """
        CREATE TABLE meta (
            key   TEXT PRIMARY KEY NOT NULL,
            value TEXT NOT NULL
        );

        -- Deep-sky objects (OpenNGC). constellation is the IAU abbreviation computed from the
        -- J2000 position (Roman 1987).
        CREATE TABLE objects (
            id                     TEXT PRIMARY KEY NOT NULL,
            type                   TEXT NOT NULL,
            ra_hours               REAL NOT NULL,
            dec_degrees            REAL NOT NULL,
            constellation          TEXT NOT NULL,
            magnitude              REAL,
            magnitude_band         TEXT,
            surface_brightness     REAL,
            major_axis_arcmin      REAL,
            minor_axis_arcmin      REAL,
            position_angle_degrees REAL,
            common_name            TEXT NOT NULL,
            source                 TEXT NOT NULL
        );

        -- Cross-identifications: M, NGC, IC, C (Caldwell) and other catalogues.
        CREATE TABLE designations (
            object_id   TEXT NOT NULL REFERENCES objects (id),
            designation TEXT NOT NULL,
            catalog     TEXT NOT NULL,
            PRIMARY KEY (object_id, designation)
        );

        -- Common names other than objects.common_name.
        CREATE TABLE names (
            object_id TEXT NOT NULL REFERENCES objects (id),
            name      TEXT NOT NULL,
            PRIMARY KEY (object_id, name)
        );

        -- Stars (HYG), J2000 epoch and equinox.
        CREATE TABLE stars (
            hyg_id        INTEGER PRIMARY KEY NOT NULL,
            hip           INTEGER,
            hd            INTEGER,
            hr            INTEGER,
            proper_name   TEXT,
            bayer         TEXT,
            flamsteed     INTEGER,
            constellation TEXT NOT NULL,
            ra_hours      REAL NOT NULL,
            dec_degrees   REAL NOT NULL,
            magnitude     REAL NOT NULL,
            color_index   REAL,
            pm_ra_mas     REAL,
            pm_dec_mas    REAL,
            -- Schema 2 (M6a): what HYG says about the star beyond its position.
            spectral_type TEXT,
            distance_pc   REAL,
            variable      TEXT,
            var_min       REAL,
            var_max       REAL,
            component     INTEGER,
            comp_primary  INTEGER,
            system        TEXT
        );

        -- Double stars (Washington Double Star Catalog) matched to a HYG star (schema 2).
        CREATE TABLE double_stars (
            hyg_id            INTEGER NOT NULL REFERENCES stars (hyg_id),
            wds_id            TEXT NOT NULL,
            discoverer        TEXT NOT NULL,
            components        TEXT NOT NULL,
            first_year        INTEGER,
            last_year         INTEGER NOT NULL,
            pa_degrees        REAL,
            separation_arcsec REAL NOT NULL,
            magnitude1        REAL NOT NULL,
            magnitude2        REAL NOT NULL,
            spectral_type     TEXT,
            PRIMARY KEY (wds_id, discoverer, components)
        );

        CREATE INDEX stars_magnitude ON stars (magnitude);
        CREATE INDEX double_stars_hyg ON double_stars (hyg_id);
        CREATE INDEX designations_designation ON designations (designation);
        """;
}
